// uses-old depends on shared-pkg, and its nested node_modules pins the older
// 1.0.0. Node-style resolution gives it the nested copy, so `shared` here is a
// different installed version (and a different runtime principal) than the
// app's top-level shared-pkg@2.0.0.
var shared = require("shared-pkg");
module.exports.readerVersion = shared.v;
module.exports.read = function read(p) {
  return shared.read(p);
};
